function subscriptionGate(){const org=S.session.organizations.find(x=>x.id===S.orgId)||S.session.organizations[0],plans=[['essential',79],['growth',129],['pro',199]];return `<main class="login-shell"><section class="login-card subscription-card">${brand()}<span class="eyebrow">${esc(org?.name||'NestLocal')}</span><h1>${t('choosePlan')}</h1><p>${t('choosePlanHelp')}</p><div class="plan-grid">${plans.map(([id,price])=>`<article class="plan-option ${id==='growth'?'featured':''}"><strong>${t(id)}</strong><span>R$ ${price}/mês</span><small>${t(`${id}Desc`)}</small><a class="button ${id==='growth'?'primary':''}" href="https://www.millionsnest.com/checkout?app=nestlocal&plan=nestlocal_${id}_monthly">${t('subscribe')}</a></article>`).join('')}</div><button class="button login-button" id="logout">${t('logout')}</button>${lang()}</section></main>`}
