function row(r){
  const fromAutopilot=S.autopilotRequestId===r.id,q=r.quote||{},ini=(r.customer?.name||'?').split(' ').map(x=>x[0]).slice(0,2).join(''),photos=(r.attachments||[]).map((_x,i)=>`<button class="button tiny" data-photo="/api/organizations/${encodeURIComponent(S.orgId)}/nestlocal/requests/${encodeURIComponent(r.id)}/photos/${i}">Foto ${i+1}</button>`).join(''),wa=String(r.customer?.phone||'').replace(/\D/g,''),when=r.preference?.date?`${r.preference.date} · ${t(r.preference.window)}`:'—',schedule=r.schedule||{},commercial=r.commercial||{},ret=r.return||{},execution=r.execution||{},finalValue=Number(commercial.finalAmountCents??q.totalCents??0)/100,paidValue=Number(commercial.amountPaidCents||0)/100;
  return `<details class="request" data-request-card="${esc(r.id)}" ${S.focusRequestId===r.id?'open':''}><summary><div class="avatar">${esc(ini)}</div><div><strong>${esc(r.customer?.name||'—')}</strong><p>${esc(r.serviceId)} · ${money(commercial.finalAmountCents??q.totalCents)}</p></div><span class="tag">${t(r.status)}</span></summary><div class="request-detail">${fromAutopilot?`<div class="autopilot-context"><span>${t('openedFromAutopilot')}</span><button class="button tiny" type="button" data-return-autopilot="true">${t('returnToQueue')}</button></div>`:''}<p><strong>${t('phone')}:</strong> ${esc(r.customer?.phone||'—')}</p><p><strong>${t('address')}:</strong> ${esc(r.address?.line||'—')} · ${esc(r.address?.city||r.address?.coverageCode||'—')}</p><p><strong>${t('preferredDate')}:</strong> ${esc(when)}</p><p><strong>${t('note')}:</strong> ${esc(r.note||'—')}</p>${q.reasons?.length?`<p><strong>${t('review')}:</strong> ${esc(q.reasons.join(', '))}</p>`:''}<div class="request-actions">${wa?`<a class="button primary small" target="_blank" rel="noopener" href="https://wa.me/${esc(wa)}">${t('contact')}</a>`:''}${photos}</div><select class="status-select" data-request="${esc(r.id)}">${['new','reviewing','quoted','accepted','scheduled','in_progress','completed','declined','cancelled'].map(status=>`<option ${r.status===status?'selected':''} value="${status}">${t(status)}</option>`).join('')}</select><form class="lifecycle-form" data-lifecycle="${esc(r.id)}"><div class="section-title"><h3>${t('lifecycleTitle')}</h3></div><label>${t('scheduledDate')}<input name="scheduledDate" type="date" value="${esc(schedule.date||r.preference?.date||'')}"></label><label>${t('scheduledWindow')}<select name="scheduledWindow">${['morning','afternoon','evening','flexible'].map(x=>`<option value="${x}" ${(schedule.window||r.preference?.window)===x?'selected':''}>${t(x)}</option>`).join('')}</select></label><label>${t('assignedTo')}<select name="assignedTo"><option value="">${t('chooseAssignee')}</option>${(S.data.team||[]).filter(m=>m.nestlocalEnabled).map(m=>`<option value="${esc(m.uid)}" ${schedule.assignedTo===m.uid?'selected':''}>${esc(m.name||m.email||m.uid)}</option>`).join('')}</select></label><label>${t('finalAmount')}<input name="finalAmount" type="number" min="0" step=".01" value="${Number.isFinite(finalValue)?finalValue:''}"></label><label>${t('paymentStatus')}<select name="paymentStatus">${['pending','partial','paid','cancelled'].map(x=>`<option value="${x}" ${(commercial.paymentStatus||'pending')===x?'selected':''}>${t(x)}</option>`).join('')}</select></label><label>${t('amountPaid')}<input name="amountPaid" type="number" min="0" step=".01" value="${Number.isFinite(paidValue)?paidValue:''}"></label><label>${t('nextServiceDate')}<input name="nextServiceDate" type="date" value="${esc(ret.nextServiceDate||'')}"></label><label>${t('returnReason')}<input name="returnReason" value="${esc(ret.reason||'')}"></label><label class="wide">${t('executionNotes')}<textarea name="executionNotes" rows="3">${esc(execution.notes||'')}</textarea></label><div class="wide lifecycle-actions"><button class="button small" type="submit">${t('saveOperation')}</button>${fromAutopilot?`<button class="button primary small" type="submit" data-save-next="true">${t('saveAndNext')}</button>`:''}<button class="button primary small" type="button" data-confirm-schedule="${esc(r.id)}">${t('confirmSchedule')}</button></div></form></div></details>`;
}
function reactivationRow(c){
  const phone=String(c.phone||'').replace(/\D/g,''),msg=encodeURIComponent(t('reactivationMessage')),whatsappAllowed=c.messaging?.consents?.maintenanceReminders?.accepted===true;
  return `<div class="reactivation-row"><div><strong>${esc(c.name||'—')}</strong><span>${esc(c.nextServiceDate||'—')} · ${esc(c.nextServiceReason||c.lastServiceId||'')}</span>${phone&&!whatsappAllowed?`<small class="consent-status blocked">${t('whatsappNoOptIn')}</small>`:''}</div><div><small>${t('lifetimeRevenue')}: ${money(c.lifetimeRevenueCents||0)}</small><div class="assistance-actions">${phone&&whatsappAllowed?`<a class="button small" target="_blank" rel="noopener" href="https://wa.me/${esc(phone)}?text=${msg}">WhatsApp</a><button class="button small" data-assistance="customer_reactivation" data-assistance-channel="whatsapp" data-customer-id="${esc(c.id)}">${t('recordWhatsapp')}</button>`:''}${phone?`<a class="button small" href="tel:+${esc(phone)}">${t('call')}</a><button class="button small" data-assistance="customer_reactivation" data-assistance-channel="phone" data-customer-id="${esc(c.id)}">${t('recordCall')}</button>`:''}</div></div></div>`;
}


const localDateIso=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const timestampMs=value=>{if(!value)return 0;if(typeof value==='string')return Date.parse(value)||0;if(Number.isFinite(value._seconds))return value._seconds*1000;if(Number.isFinite(value.seconds))return value.seconds*1000;return 0};
const weekdayIds=['sun','mon','tue','wed','thu','fri','sat'];
const weekdayShortToIndex={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
function zonedDateInfo(date,timeZone){
  try{
    const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone,year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));
    return {date:`${parts.year}-${parts.month}-${parts.day}`,weekday:weekdayShortToIndex[parts.weekday],hour:Number(parts.hour)};
  }catch{return null}
}
function organizationDateIso(){
  const timeZone=S.data.settings?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
  return zonedDateInfo(new Date(),timeZone)?.date||localDateIso();
}
function smartFillSnapshot(){
  const settings=S.data.settings||{},capacity=settings.capacity||{},workingDays=Array.isArray(capacity.workingDays)?capacity.workingDays.map(Number):[],windows=Array.isArray(capacity.windows)?capacity.windows:[],team=(S.data.team||[]).filter(x=>x.nestlocalEnabled);
  if(!workingDays.length||!windows.length||!team.length)return {configured:false,slots:[],due:[],matchCount:0};
  const timeZone=settings.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',requests=S.data.requests||[],now=new Date(),today=zonedDateInfo(now,timeZone),slots=[];
  for(let offset=0;offset<7;offset++){
    const instant=new Date(now.getTime()+offset*86400000),info=zonedDateInfo(instant,timeZone);if(!info||!workingDays.includes(info.weekday))continue;
    for(const window of windows){
      if(offset===0&&today?.date===info.date){
        if(window==='morning'&&info.hour>=12)continue;
        if(window==='afternoon'&&info.hour>=17)continue;
        if(window==='evening'&&info.hour>=22)continue;
      }
      for(const member of team){
        const occupied=requests.some(r=>['scheduled','in_progress'].includes(r.status)&&r.schedule?.date===info.date&&r.schedule?.window===window&&r.schedule?.assignedTo===member.uid);
        if(!occupied)slots.push({date:info.date,window,memberId:member.uid,memberName:member.name||member.email||member.uid});
      }
    }
  }
  const todayIso=today?.date||localDateIso(),due=(S.data.customers||[]).filter(c=>c.nextServiceDate&&c.nextServiceDate<=todayIso);
  return {configured:true,slots,due,matchCount:Math.min(slots.length,due.length),timeZone};
}
function smartFillCard(){
  const fill=smartFillSnapshot();
  if(!fill.configured)return `<article class="card smart-fill-card"><div class="section-title"><div><h2>${t('smartFill')}</h2><p class="help">${t('capacityNotConfigured')}</p></div></div><button class="button small" data-action-page="services">${t('configureCapacity')}</button></article>`;
  return `<article class="card smart-fill-card"><div class="section-title"><div><h2>${t('smartFill')}</h2><p class="help">${t('smartFillHelp')}</p></div><span class="tag">${esc(fill.timeZone||'')}</span></div><div class="smart-fill-metrics"><div><strong>${fill.slots.length}</strong><span>${t('freeSlots')}</span></div><div><strong>${fill.due.length}</strong><span>${t('dueCustomers')}</span></div><div class="highlight"><strong>${fill.matchCount}</strong><span>${t('possibleMatches')}</span></div></div>${fill.matchCount?`<div class="smart-fill-slots">${fill.slots.slice(0,5).map(slot=>`<div><strong>${esc(slot.date)} · ${t(slot.window)}</strong><span>${esc(slot.memberName)}</span></div>`).join('')}</div><button class="button small" data-scroll-reactivation="true">${t('reactivationQueue')}</button>`:`<div class="empty">${t('noSmartFill')}</div>`}</article>`;
}

function opportunityPulseCard(){
  const snapshot=buildOpportunitySnapshot({requests:S.data.requests||[],customers:S.data.customers||[],now:Date.now(),today:organizationDateIso(),fill:smartFillSnapshot(),readiness:S.data.reminderReadiness||{},timestampMs,actions:nextBestActions()});
  return renderOpportunityPulse({snapshot,t,esc,money});
}

function outcomeLearningCard(){return renderOutcomeLearning({snapshot:S.data.actionOutcomeMetrics||{},t,esc})}

function nextBestActions(){
  const requests=S.data.requests||[],customers=S.data.customers||[],today=organizationDateIso(),now=Date.now(),actions=[];
  for(const r of requests){
    const customerName=r.customer?.name||'—',amount=r.commercial?.finalAmountCents??r.quote?.totalCents??0,phone=r.customer?.phone||'';
    if(r.status==='in_progress')actions.push({type:'finish',priority:100,requestId:r.id,customerName,amount});
    else if(r.status==='accepted')actions.push({type:'schedule',priority:96,requestId:r.id,customerName,amount});
    else if(r.status==='scheduled'&&(r.schedule?.date||r.preference?.date)&&String(r.schedule?.date||r.preference?.date)<=today)actions.push({type:'execute',priority:92,requestId:r.id,customerName,amount,dueDate:r.schedule?.date||r.preference?.date});
    else if(['new','reviewing'].includes(r.status))actions.push({type:'review',priority:82,requestId:r.id,customerName,amount});
    else if(r.status==='quoted'){
      const created=timestampMs(r.updatedAt)||timestampMs(r.createdAt);
      if((!created||now-created>=48*60*60*1000)&&actionCooldownAllows(r,'quote_followup',today))actions.push({type:'followup',priority:76,requestId:r.id,customerName,amount,phone,serviceId:r.serviceId,ageHours:created?Math.floor((now-created)/(60*60*1000)):48,whatsappAllowed:r.messagingConsent?.serviceUpdates?.accepted===true,lastOutcome:r.lastAssistanceOutcome?.outcome||'',lastOutcomeNote:r.lastAssistanceOutcome?.outcomeNote||''});
    } else if(r.status==='completed'&&['pending','partial'].includes(r.commercial?.paymentStatus||'')){
      actions.push({type:'collect',priority:72,requestId:r.id,customerName,phone,serviceId:r.serviceId,amount:Math.max(0,Number(r.commercial?.finalAmountCents??r.quote?.totalCents??0)-Number(r.commercial?.amountPaidCents||0))});
    }
  }
  for(const c of customers){
    if(c.nextServiceDate&&c.nextServiceDate<=today&&actionCooldownAllows(c,'customer_reactivation',today))actions.push({type:'reactivate',priority:66,customerId:c.id,customerName:c.name||'—',phone:c.phone||'',serviceLabel:c.nextServiceReason||c.lastServiceId||'',dueDate:c.nextServiceDate,amount:c.lifetimeRevenueCents||0,whatsappAllowed:c.messaging?.consents?.maintenanceReminders?.accepted===true,lastOutcome:c.lastAssistanceOutcome?.outcome||'',lastOutcomeNote:c.lastAssistanceOutcome?.outcomeNote||''});
  }
  return actions.sort((a,b)=>b.priority-a.priority||String(a.customerName).localeCompare(String(b.customerName))).slice(0,20);
}
function actionControls(a){
  if(['followup','collect','reactivate'].includes(a.type))return `<button class="button primary small" data-action-assist="${esc(assistActionKey(a))}">${t('prepareContact')}</button>`;
  return `<button class="button small" data-open-request="${esc(a.requestId||'')}">${t('openRequests')}</button>`;
}
function actionServiceLabel(a){
  if(a.serviceLabel)return a.serviceLabel;
  const service=(S.data.services||[]).find(x=>x.id===a.serviceId);
  return service?serviceName(service):(a.serviceId||'');
}
function actionAssistantOverlay(){
  const action=S.actionAssist;if(!action)return '';
  const playbook=buildActionPlaybook({action,lang:S.lang,businessName:S.data.settings?.businessName||'',serviceLabel:actionServiceLabel(action),formatMoney:money});
  if(!playbook)return '';
  const readiness=officialMessageReadiness(action,S.data.settings||{}),phone=String(playbook.phone||'').replace(/\D/g,''),msg=encodeURIComponent(playbook.message),actionType=action.type==='followup'?'quote_followup':action.type==='reactivate'?'customer_reactivation':'';
  const facts=playbook.facts.map(f=>`<div class="assist-fact"><span>${t(f.key)}</span><strong>${esc(f.key==='fact_quote_wait'?`${f.value} ${t('hoursShort')}`:f.value)}</strong></div>`).join('');
  const officialLabel=!readiness.supported?t('officialUnsupported'):readiness.ready?t('officialReady'):`${t('officialBlocked')} · ${t(`messageBlock_${readiness.reason}`)}`;
  const whatsappStatus=playbook.whatsappAllowed?t('channelPurposeOk'):t('channelPurposeBlocked');
  const whatsappButton=playbook.whatsappAllowed&&phone?`<a class="button primary" target="_blank" rel="noopener" href="https://wa.me/${esc(phone)}?text=${msg}">${t('openWhatsapp')}</a>`:'';
  const recordButton=playbook.whatsappAllowed&&phone&&actionType?`<button class="button" data-assistance="${esc(actionType)}" data-assistance-channel="whatsapp" data-request-id="${esc(action.requestId||'')}" data-customer-id="${esc(action.customerId||'')}">${t('recordWhatsapp')}</button>`:'';
  const phoneButton=phone?`<a class="button" href="tel:+${esc(phone)}">${t('call')}</a>`:'';
  const recordCallButton=phone&&actionType?`<button class="button" data-assistance="${esc(actionType)}" data-assistance-channel="phone" data-request-id="${esc(action.requestId||'')}" data-customer-id="${esc(action.customerId||'')}">${t('recordCall')}</button>`:'';
  const prepareButton=readiness.ready?`<button class="button" data-prepare-official="${esc(assistActionKey(action))}">${t('prepareOfficial')}</button>`:'';
  const requestButton=action.requestId?`<button class="button" data-open-request="${esc(action.requestId)}">${t('openRequests')}</button>`:'';
  const defaultSnooze=action.type==='followup'?2:1;
  const snoozeControl=actionType?`<label class="assist-snooze">${t('remindAfterContact')}<select id="action-snooze-days"><option value="1" ${defaultSnooze===1?'selected':''}>${t('remindTomorrow')}</option><option value="2" ${defaultSnooze===2?'selected':''}>${t('remind2Days')}</option><option value="7">${t('remind7Days')}</option></select><small>${t('remindHelp')}</small></label>`:'';
  const outcomeLabel=value=>value==='no_response'?t('outcomeNoResponse'):value==='asked_later'?t('outcomeAskedLater'):value==='positive_signal'?t('outcomePositive'):value==='not_interested'?t('outcomeNotInterested'):t('outcomeUnresolved');
  const previousOutcome=action.lastOutcome?`<div class="assist-previous-outcome"><span>${t('previousOutcome')}</span><strong>${esc(outcomeLabel(action.lastOutcome))}</strong>${action.lastOutcomeNote?`<small>${esc(action.lastOutcomeNote)}</small>`:''}</div>`:'';
  const outcomeControl=actionType?`<div class="assist-outcome">${previousOutcome}<label>${t('contactOutcome')}<select id="action-outcome"><option value="unresolved">${t('outcomeUnresolved')}</option><option value="no_response">${t('outcomeNoResponse')}</option><option value="asked_later">${t('outcomeAskedLater')}</option><option value="positive_signal">${t('outcomePositive')}</option><option value="not_interested">${t('outcomeNotInterested')}</option></select></label><label>${t('outcomeNote')}<input id="action-outcome-note" maxlength="180" placeholder="${esc(t('outcomeNotePlaceholder'))}"></label><small>${t('outcomeHelp')}</small></div>`:'';

  return `<div class="assist-backdrop" data-close-assist="backdrop"><section class="action-assistant" role="dialog" aria-modal="true" aria-label="${esc(t('actionAssistant'))}"><div class="assist-head"><div><span class="eyebrow">${t('actionAssistant')}</span><h2>${t(`action_${action.type}`)}</h2><p class="help">${t('actionAssistantHelp')}</p></div><button class="button tiny" data-close-assist="button" aria-label="${esc(t('close'))}">${t('close')}</button></div><div class="assist-message"><span>${t('suggestedMessage')}</span><textarea id="action-assist-message" readonly rows="5">${esc(playbook.message)}</textarea><button class="button small" data-copy-assist="true">${t('copyMessage')}</button></div><div class="assist-facts"><span class="assist-label">${t('basedOnFacts')}</span>${facts||'<div class="empty">—</div>'}</div><div class="assist-readiness"><div class="${playbook.whatsappAllowed?'ready':'blocked'}"><span>WhatsApp</span><strong>${esc(whatsappStatus)}</strong></div><div class="${readiness.ready?'ready':'blocked'}"><span>${t('messagingSetup')}</span><strong>${esc(officialLabel)}</strong><small>${t('prepareOfficialHelp')}</small></div></div>${outcomeControl}${snoozeControl}<div class="assist-actions"><button class="button" data-copy-assist="true">${t('copyMessage')}</button>${whatsappButton}${phoneButton}${prepareButton}${recordButton}${recordCallButton}${requestButton}</div></section></div>`;
}

function actionReason(a){
  return t(a.reasonKey).replace('{n}',String(a.reasonValue||0));
}
function urgencyLabel(a){
  return a.urgency==='now'?t('focusNow'):a.urgency==='next'?t('focusNext'):t('focusOpportunity');
}
function actionRow(a){
  return `<div class="next-action"><div><span class="action-priority ${esc(a.urgency||'')}">${urgencyLabel(a)}</span><strong>${t(`action_${a.type}`)}</strong><small>${esc(a.customerName)}${a.dueDate?` · ${esc(a.dueDate)}`:''}${a.amount?` · ${money(a.amount)}`:''}</small><p class="action-reason"><b>${t('whyNow')}</b> ${esc(actionReason(a))}</p></div><div class="assistance-actions">${actionControls(a)}</div></div>`;
}
function focusQueueCard(actions){
  const queue=buildFocusQueue(actions,organizationDateIso());
  if(!queue.focus)return '';
  const focus=queue.focus;
  return `<article class="card focus-queue"><div class="section-title"><div><h2>${t('focusQueue')}</h2><p class="help">${t('focusQueueHelp')}</p></div><span>${queue.total}</span></div><section class="focus-action"><div class="focus-copy"><span class="action-priority ${esc(focus.urgency)}">${urgencyLabel(focus)}</span><h3>${t(`action_${focus.type}`)}</h3><p class="focus-person">${esc(focus.customerName)}${focus.dueDate?` · ${esc(focus.dueDate)}`:''}${focus.amount?` · ${money(focus.amount)}`:''}</p><div class="why-card"><span>${t('whyNow')}</span><strong>${esc(actionReason(focus))}</strong></div></div><div class="focus-controls assistance-actions">${actionControls(focus)}</div></section>${queue.next.length?`<div class="focus-next"><div class="focus-next-head"><strong>${t('focusNext')}</strong>${queue.remainingCount?`<span>+${queue.remainingCount} ${t('moreActions')}</span>`:''}</div>${queue.next.map(actionRow).join('')}</div>`:''}</article>`;
}


function today(){
  const a=S.data.requests||[],customers=S.data.customers||[],assisted=S.data.revenueMetrics||{},open=a.filter(x=>!['completed','declined','cancelled'].includes(x.status)),revenue=open.reduce((n,x)=>n+(x.commercial?.finalAmountCents??x.quote?.totalCents??0),0),priced=a.filter(x=>x.quote?.outcome==='priced').length,done=a.filter(x=>x.status==='completed').length,todayIso=organizationDateIso(),returns=customers.filter(c=>c.nextServiceDate&&c.nextServiceDate<=todayIso),actions=nextBestActions();
  return `<div class="grid metrics"><article class="card metric highlight"><span>${t('action')}</span><strong>${actions.length}</strong><small>${t('actionEngineHelp')}</small></article><article class="card metric"><span>${t('open')}</span><strong>${money(revenue)}</strong><small>${t('requests')}</small></article><article class="card metric assisted-metric"><span>${t('assistedRevenue')}</span><strong>${money(assisted.assistedRevenueCents||0)}</strong><small>${esc(assisted.assistedJobs||0)} · ${t('assistedRevenueHelp')}</small></article><article class="card metric"><span>${t('conversion')}</span><strong>${priced?Math.round(done/priced*100):0}%</strong><small>${t('completed')}</small></article></div>${opportunityPulseCard()}${smartFillCard()}${focusQueueCard(actions)}${outcomeLearningCard()}<article class="card"><div class="section-title"><h2>${t('inbox')}</h2><span>${a.length}</span></div>${a.length?a.slice(0,12).map(row).join(''):`<div class="empty">${t('empty')}</div>`}</article>${returns.length?`<article class="card reactivation-card"><div class="section-title"><div><h2>${t('reactivationQueue')}</h2><p class="help">${t('reactivationHelp')}</p></div><span>${returns.length}</span></div><div class="reactivation-list">${returns.map(reactivationRow).join('')}</div></article>`:''}`;
}
