  if(S.tracking){const q=S.tracking.quote||{},tokenValue=new URLSearchParams(location.search).get('token')||'',amount=S.tracking.displayTotalCents??q.totalCents;return `<main class="public-shell"><section class="public-card">${brand()}<span class="eyebrow">${t('tracking')}</span><h1>${t(S.tracking.status)}</h1>${amount!=null?`<div class="result-price">${money(amount)}</div>`:''}<p>${esc(S.tracking.serviceId)} · ${esc(S.tracking.quantity)}</p>${S.tracking.status==='accepted'?`<div class="notice decision-success"><strong>${t('quoteApproved')}</strong><span>${t('scheduleNext')}</span></div>`:S.tracking.status==='declined'?`<div class="notice"><strong>${t('quoteDeclined')}</strong></div>`:''}${S.tracking.canDecide?`<div class="quote-decision"><p>${t('decisionHelp')}</p><button class="button primary" data-decision="accepted" data-request-id="${esc(S.tracking.id)}" data-token="${esc(tokenValue)}">${t('approveQuote')}</button><button class="button" data-decision="declined" data-request-id="${esc(S.tracking.id)}" data-token="${esc(tokenValue)}">${t('declineQuote')}</button></div>`:''}</section></main>`}
  if(S.result){const q=S.result.quote,track=`${location.origin}/track/${S.result.requestId}?token=${encodeURIComponent(S.result.trackingToken)}`,wa=String(S.store?.store?.whatsapp||'').replace(/\D/g,''),msg=encodeURIComponent(`Olá! Acabei de enviar o pedido ${S.result.requestId} pelo NestLocal.`),canDecide=q.outcome==='priced'&&q.totalCents!=null;return `<main class="public-shell"><section class="public-card"><span class="tag">${t('requestSent')}</span><h1>${q.outcome==='priced'?t('ready'):q.outcome==='unavailable'?t('unavailable'):t('review')}</h1>${q.totalCents!=null?`<div class="result-price">${money(q.totalCents)}</div>`:''}${canDecide?`<div class="quote-decision"><p>${t('decisionHelp')}</p><button class="button primary" data-decision="accepted" data-request-id="${esc(S.result.requestId)}" data-token="${esc(S.result.trackingToken)}">${t('approveQuote')}</button><button class="button" data-decision="declined" data-request-id="${esc(S.result.requestId)}" data-token="${esc(S.result.trackingToken)}">${t('declineQuote')}</button></div>`:''}<div class="result-actions">${wa?`<a class="button" target="_blank" rel="noopener" href="https://wa.me/${esc(wa)}?text=${msg}">${t('contact')}</a>`:''}<a class="button" href="${esc(track)}">${t('track')}</a></div></section></main>`}
  const x=S.store,today=new Date().toISOString().slice(0,10),selected=x.services.find(s=>s.id===(S.publicServiceId||x.services[0]?.id))||x.services[0];return `<main class="public-shell"><section class="public-card wide-public"><div class="public-brand">${brand()}${lang()}</div><span class="eyebrow">${esc(x.store.businessName)}</span><h1>${t('publicTitle')}</h1><p>${t('publicHelp')}</p><form id="public" class="form-grid"><label class="wide">${t('selectService')}<select id="public-service" name="serviceId">${x.services.map(s=>`<option value="${esc(s.id)}" ${selected?.id===s.id?'selected':''}>${esc(serviceName(s))}${s.mode==='fixed'?` · ${t('startingAt')} ${money(s.unitPriceCents)}`:''}</option>`).join('')}</select></label><label>${t('name')}<input name="name" autocomplete="name" required></label><label>${t('phone')}<input name="phone" autocomplete="tel" required inputmode="tel"></label><label>${t('city')}<select name="coverageCode">${x.store.coverageCodes.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label>${t('quantity')}<input name="quantity" type="number" min="1" max="10" value="1"></label><label class="wide">${t('address')}<input name="addressLine" autocomplete="street-address" required minlength="5"></label><label>${t('preferredDate')}<input name="preferredDate" type="date" min="${today}" required></label><label>${t('preferredWindow')}<select name="preferredWindow"><option value="morning">${t('morning')}</option><option value="afternoon">${t('afternoon')}</option><option value="evening">${t('evening')}</option><option value="flexible">${t('flexible')}</option></select></label>${selected?.requiresEquipmentType!==false?`<label>${t('equipment')}<select name="equipmentType"><option value="split">Split</option><option value="other">${t('other')}</option></select></label>`:''}${selected?.requiresSafeAccess!==false?`<label>${t('access')}<select name="safeAccess"><option value="true">${t('yes')}</option><option value="false">${t('unsure')}</option></select></label>`:''}<label class="wide">${t('note')}<textarea name="note" rows="3"></textarea></label><label class="wide">${t('photos')}<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label class="wide consent"><input name="whatsappServiceOptIn" type="checkbox"><span>${esc(replaceBusiness('whatsappServiceOptIn',x.store.businessName))}</span></label><label class="wide consent"><input name="whatsappMaintenanceOptIn" type="checkbox"><span>${esc(replaceBusiness('whatsappMaintenanceOptIn',x.store.businessName))}</span></label>${publicConsentAnchor}<button class="button primary wide">${t('send')}</button></form></section></main>`
