  document.querySelectorAll('[data-action-assist]').forEach(button=>button.onclick=()=>{const key=button.dataset.actionAssist,action=nextBestActions().find(a=>assistActionKey(a)===key);if(!action)return;S.actionAssist=action;render()});
  document.querySelectorAll('[data-close-assist]').forEach(button=>button.onclick=e=>{if(button.dataset.closeAssist==='backdrop'&&e.target!==button)return;S.actionAssist=null;render()});
