  document.querySelectorAll('[data-prepare-official]').forEach(button=>button.onclick=async()=>{const action=S.actionAssist;if(!action)return;button.disabled=true;try{const category=action.type==='followup'?'service_update':'maintenance_reminder',result=await api(`/api/organizations/${S.orgId}/nestlocal/messages/prepare`,{method:'POST',body:JSON.stringify({category,requestId:action.requestId||undefined,customerId:action.customerId||undefined})});await loadData();S.actionAssist=null;render();toast(result.status==='ready'?t('messagePrepared'):t(`messageBlock_${result.eligibility?.reason||result.blockReason||'UNKNOWN'}`))}catch(err){button.disabled=false;toast(err.message)}});

  document.querySelectorAll('[data-assistance]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const outcome=document.querySelector('#action-outcome')?.value||'unresolved',outcomeNote=document.querySelector('#action-outcome-note')?.value||'',snoozeDays=Number(document.querySelector('#action-snooze-days')?.value||1);await api(`/api/organizations/${S.orgId}/nestlocal/action-events`,{method:'POST',body:JSON.stringify({actionType:button.dataset.assistance,channel:button.dataset.assistanceChannel||'other',requestId:button.dataset.requestId||undefined,customerId:button.dataset.customerId||undefined,outcome,outcomeNote,snoozeDays})});await loadData();S.actionAssist=null;render();toast(t('contactRecordedSnoozed'))}catch(err){button.disabled=false;toast(err.message==='FOLLOWUP_NOT_DUE'?t('followupNotDue'):err.message==='REACTIVATION_NOT_DUE'?t('reactivationNotDue'):err.message==='WHATSAPP_OPT_IN_REQUIRED'?t('whatsappOptInRequired'):err.message)}});

  document.querySelectorAll('[data-lang]').forEach(x=>x.onchange=()=>{S.lang=x.value;localStorage.setItem('nl_lang',S.lang);render()});
  document.querySelector('#login')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent=t('loading');try{sessionStorage.setItem('nl_auth_started_at',String(Date.now()));await signInWithRedirect(auth,googleProvider())}catch(err){button.disabled=false;button.textContent=t('login');toast(err.message)}});
  document.querySelector('#logout')?.addEventListener('click',()=>signOut(auth));
  document.querySelector('#org')?.addEventListener('change',async e=>{S.actionAssist=null;S.focusRequestId='';S.autopilotRequestId='';S.orgId=e.target.value;localStorage.setItem('nl_org',S.orgId);S.loading=true;render();const org=S.session.organizations.find(x=>x.id===S.orgId);if(org?.nestlocal?.access)await loadData();else S.data={organization:org,entitlement:org?.nestlocal};S.loading=false;render()});
  document.querySelector('#bootstrap-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api(`/api/organizations/${S.orgId}/nestlocal/bootstrap`,{method:'POST',body:JSON.stringify({template:f.get('template')||'climate'})});await loadData();render()});
