  document.querySelectorAll('[data-request]').forEach(x=>x.onchange=async()=>{x.disabled=true;try{const fromAutopilot=S.autopilotRequestId===x.dataset.request;await api(`/api/organizations/${S.orgId}/nestlocal/requests/${x.dataset.request}`,{method:'PATCH',body:JSON.stringify({status:x.value})});await loadData();if(fromAutopilot)returnToAutopilotQueue();else render()}catch(err){await loadData();render();toast(err.message==='SCHEDULE_CONFLICT'?t('scheduleConflict'):err.message==='SCHEDULE_REQUIRED'?t('scheduleRequired'):err.message==='INVALID_ASSIGNEE'?t('invalidAssignee'):err.message)}});
