  document.querySelectorAll('[data-confirm-schedule]').forEach(button=>button.onclick=async()=>{const form=button.closest('[data-lifecycle]'),f=new FormData(form),payload={status:'scheduled',scheduledDate:f.get('scheduledDate')||'',scheduledWindow:f.get('scheduledWindow')||'flexible',assignedTo:f.get('assignedTo')||''};button.disabled=true;try{const fromAutopilot=S.autopilotRequestId===form.dataset.lifecycle;await api(`/api/organizations/${S.orgId}/nestlocal/requests/${form.dataset.lifecycle}`,{method:'PATCH',body:JSON.stringify(payload)});await loadData();if(fromAutopilot)returnToAutopilotQueue();else{render();toast(t('confirmSchedule'))}}catch(err){button.disabled=false;toast(err.message==='SCHEDULE_CONFLICT'?t('scheduleConflict'):err.message==='SCHEDULE_REQUIRED'?t('scheduleRequired'):err.message==='INVALID_ASSIGNEE'?t('invalidAssignee'):err.message)}});


