  document.querySelector('#public-service')?.addEventListener('change',e=>{S.publicServiceId=e.target.value;render()});
  document.querySelector('#public')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"],button:not([type])'),f=new FormData(form),photos=[...(form.elements.photos?.files||[])],b=Object.fromEntries(f);delete b.photos;b.quantity=Number(b.quantity);b.safeAccess=b.safeAccess==='true';b.acceptedTerms=f.get('acceptedTerms')==='on';b.whatsappServiceOptIn=f.get('whatsappServiceOptIn')==='on';b.whatsappMaintenanceOptIn=f.get('whatsappMaintenanceOptIn')==='on';b.city=b.coverageCode;button.disabled=true;try{S.result=await api(`/api/public/stores/${encodeURIComponent(publicSlug())}/requests`,{method:'POST',body:JSON.stringify(b)});if(photos.length){const uploads=new FormData();photos.slice(0,5).forEach(file=>uploads.append('photos',file));try{await api(`/api/public/requests/${S.result.requestId}/photos?token=${encodeURIComponent(S.result.trackingToken)}`,{method:'POST',body:uploads})}catch(err){toast(`Pedido salvo; fotos não enviadas: ${err.message}`)}}render()}catch(err){button.disabled=false;toast(err.message)}})
